public class TransitCardTest
{
    private static int failures = 0;

    public static void main(String[] args)
    {
        testTaps();
        if(failures == 0) {
            System.out.println("All tests passed");
        }
        else {
            System.out.println("Failures: " + failures);
        }
    }

    private static void testTaps()
    {
        TransitCard card = new TransitCard(500);
        assertTrue("first tap", card.tapOn());
        assertEquals("after first", 250,
            card.getBalance());
        assertTrue("exact fare", card.tapOn());
        assertEquals("after second", 0,
            card.getBalance());
        assertTrue("third refused", !card.tapOn());
        assertEquals("after third", 0,
            card.getBalance());
        assertTrue("negative top-up", !card.topUp(-100));
        assertEquals("after refusal", 0,
            card.getBalance());
    }

    private static void assertEquals(String label,
        int expected, int actual)
    {
        if(expected == actual) {
            System.out.println("PASS " + label);
        }
        else {
            failures++;
            System.out.println("FAIL " + label
                + ": expected " + expected
                + ", actual " + actual);
        }
    }

    private static void assertTrue(String label,
        boolean condition)
    {
        if(condition) {
            System.out.println("PASS " + label);
        }
        else {
            failures++;
            System.out.println("FAIL " + label);
        }
    }
}

