/** A target temperature between 10 and 30 inclusive. */
public class Thermostat
{
    private int target;

    /** Start at 20 degrees. */
    public Thermostat()
    {
        target = 20;
    }

    /** Refuse an invalid target without changing the old one. */
    public boolean setTarget(int target)
    {
        if(target < 10 || target > 30) {
            return false;
        }
        this.target = target;
        return true;
    }

    public int getTarget()
    {
        return target;
    }
}

